{
  "features": [
    {
      "feature_name": "bureau_active_credit_count",
      "rationale": "Counts the number of currently active credit lines, indicating current leverage and potential over-indebtedness.",
      "source_tables": [
        "bureau"
      ],
      "python_code": "def compute_bureau_active_credit_count(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    bureau['is_active'] = (bureau['CREDIT_ACTIVE'] == 'Active').astype(int)\n    agg = bureau.groupby('SK_ID_CURR').agg(val=('is_active', 'sum')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_active_credit_count')"
    },
    {
      "feature_name": "bureau_debt_to_limit_ratio",
      "rationale": "Measures the utilization rate of available credit limits, a strong predictor of cash flow stress and default risk.",
      "source_tables": [
        "bureau"
      ],
      "python_code": "def compute_bureau_debt_to_limit_ratio(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    bureau['debt_limit_ratio'] = bureau['AMT_CREDIT_SUM_DEBT'] / (bureau['AMT_CREDIT_SUM_LIMIT'] + 1)\n    agg = bureau.groupby('SK_ID_CURR').agg(val=('debt_limit_ratio', 'mean')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_debt_to_limit_ratio')"
    },
    {
      "feature_name": "bureau_max_overdue_amount",
      "rationale": "Captures the peak historical delinquency amount, reflecting the severity of past payment failures.",
      "source_tables": [
        "bureau"
      ],
      "python_code": "def compute_bureau_max_overdue_amount(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    agg = bureau.groupby('SK_ID_CURR').agg(val=('AMT_CREDIT_MAX_OVERDUE', 'max')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_max_overdue_amount')"
    },
    {
      "feature_name": "bureau_balance_dpd30_plus_count",
      "rationale": "Counts months with significant delinquency (DPD 30+), indicating persistent payment difficulties.",
      "source_tables": [
        "bureau_balance",
        "bureau"
      ],
      "python_code": "def compute_bureau_balance_dpd30_plus_count(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    bb = bureau_bal.merge(bureau[['SK_ID_BUREAU', 'SK_ID_CURR']], on='SK_ID_BUREAU', how='left')\n    bb['is_dpd30_plus'] = bb['STATUS'].isin(['1', '2', '3', '4', '5']).astype(int)\n    agg = bb.groupby('SK_ID_CURR').agg(val=('is_dpd30_plus', 'sum')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_balance_dpd30_plus_count')"
    },
    {
      "feature_name": "bureau_balance_recent_dpd_ratio",
      "rationale": "Calculates the proportion of delinquent months in the last 6 months, highlighting recent behavioral deterioration.",
      "source_tables": [
        "bureau_balance",
        "bureau"
      ],
      "python_code": "def compute_bureau_balance_recent_dpd_ratio(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    bb = bureau_bal.merge(bureau[['SK_ID_BUREAU', 'SK_ID_CURR']], on='SK_ID_BUREAU', how='left')\n    recent = bb[bb['MONTHS_BALANCE'] >= -6]\n    recent['is_dpd'] = recent['STATUS'].isin(['1', '2', '3', '4', '5']).astype(int)\n    agg = recent.groupby('SK_ID_CURR').agg(total=('is_dpd', 'count'), dpd=('is_dpd', 'sum')).reset_index()\n    agg['val'] = agg['dpd'] / (agg['total'] + 1)\n    result = app_train[['SK_ID_CURR']].merge(agg[['SK_ID_CURR', 'val']], on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_balance_recent_dpd_ratio')"
    },
    {
      "feature_name": "bureau_credit_prolong_count",
      "rationale": "Aggregates the number of credit extensions, suggesting potential liquidity issues or inability to repay on time.",
      "source_tables": [
        "bureau"
      ],
      "python_code": "def compute_bureau_credit_prolong_count(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    agg = bureau.groupby('SK_ID_CURR').agg(val=('CNT_CREDIT_PROLONG', 'sum')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('bureau_credit_prolong_count')"
    }
  ]
}
